#include "mainwindow.h"
#include "../plugins/inspection/inspection_point_editor.h"
#include <QDockWidget>
#include <QHBoxLayout>
#include <QFormLayout>
#include <QVBoxLayout>
#include <QStatusBar>
MainWindow::MainWindow(QWidget*p):QMainWindow(p){setWindowTitle("AGT Robot HMI");resize(1440,900);setStyleSheet("QMainWindow{background:#18232d;color:#d9e2e8} QWidget{background:#18232d;color:#d9e2e8} QDockWidget{font-weight:bold} QPushButton{background:#294452;border:1px solid #3d6372;padding:8px} QPushButton:hover{background:#356176} QProgressBar{border:1px solid #3d6372;text-align:center} QProgressBar::chunk{background:#2bb673}");map_=new MapWidget(this);setCentralWidget(map_);auto*dock=new QDockWidget(tr("ROBOT STATE"),this);auto*state=new QWidget(dock);auto*l=new QFormLayout(state);connection_=new QLabel(tr("ROS2 / connecting"),state);pose_=new QLabel("(—, —, —)",state);battery_=new QProgressBar(state);battery_->setRange(0,100);battery_->setValue(0);l->addRow(tr("Runtime"),connection_);l->addRow(tr("Pose"),pose_);l->addRow(tr("Battery"),battery_);dock->setWidget(state);addDockWidget(Qt::RightDockWidgetArea,dock);inspection_=new InspectionPanel(this);auto*idock=new QDockWidget(tr("INSPECTION TASK"),this);idock->setWidget(inspection_);addDockWidget(Qt::RightDockWidgetArea,idock);statusBar()->showMessage(tr("AGT Robotics Runtime interface"));connect(&ros_,&AgtRosInterface::mapReceived,map_,&MapWidget::setMap);connect(&ros_,&AgtRosInterface::poseReceived,this,[this](double x,double y,double yaw){pose_->setText(QString("(%1, %2, %3 rad)").arg(x,0,'f',2).arg(y,0,'f',2).arg(yaw,0,'f',2));map_->setPose(x,y,yaw);});connect(&ros_,&AgtRosInterface::batteryReceived,battery_,&QProgressBar::setValue);connect(&ros_,&AgtRosInterface::taskStatusReceived,inspection_,&InspectionPanel::setTaskStatus);connect(&ros_,&AgtRosInterface::visionResultReceived,inspection_,&InspectionPanel::setResult);connect(map_,&MapWidget::addInspectionPoint,this,&MainWindow::addPoint);connect(inspection_,&InspectionPanel::startRequested,&ros_,&AgtRosInterface::startTask);connect(inspection_,&InspectionPanel::pauseRequested,&ros_,&AgtRosInterface::pauseTask);connect(inspection_,&InspectionPanel::cancelRequested,&ros_,&AgtRosInterface::cancelTask);}
void MainWindow::addPoint(double x,double y){InspectionPoint p;p.id=QString("P%1").arg(inspection_->task().points.size()+1,3,10,QChar('0'));p.x=x;p.y=y;p.actions<<"capture_image"<<"inference";InspectionPointEditor e(p,this);if(e.exec()==QDialog::Accepted){auto t=inspection_->task();t.points<<e.point();inspection_->setTask(t);}}
